mapper.select:
select f.follow_user_id userId,count(1) `match` from corgi_user_follow f left join corgi_user_detail d on d.user_id = f.follow_user_id where f.is_deleted = '0' and f.type = 'real' and (d.avatar_status not like 'fake%' or d.avatar_status is null)
and f.uptime >= #{date}
and d.role = '1'
and d.role != '1'
group by f.follow_user_id order by `match` desc limit #{limit}

select count(1) `match`, user_id userId
from (
             (select user_id from corgi_activity_comment where ctime >= #{date})
             union all
             (select user_id from corgi_activity_like where ctime >= #{date} and type = 'real')
     ) a
group by user_id
order by `match` desc limit #{limit}

select user_id userId
from corgi_billboard
where `date` >= #{date}

mapper.update:
update corgi.corgi_billboard
set user_id = #{toId}
where `date` = #{date}
  and user_id = #{fromId}

mapper.insert:
update corgi_activity_billboard
set status = '1'
where activity_id = #{activityId}

mapper.select:
select count(1)
from corgi_billboard
where user_id = #{userId}
  and `date` = #{date}
